// Thumbnails live next to originals: <cdn>/images/<name>.<ext>  ->  <cdn>/thumbs/<name>.webp
// Generated by scripts/generate-thumbs.mjs (backfill) and lib/upload.js (new uploads).
export const THUMB_WIDTH = 480;

const ORIGINAL = /^(https:\/\/cdn\.[^/]+)\/images\/([^/?#]+)\.(?:png|jpe?g|webp|gif)$/i;

export function thumbUrl(url) {
  if (!url || typeof url !== 'string') return url;
  const m = url.match(ORIGINAL);
  return m ? `${m[1]}/thumbs/${m[2]}.webp` : url;
}

export function thumbKey(imageKey) {
  const m = imageKey.match(/^images\/([^/]+)\.(?:png|jpe?g|webp|gif)$/i);
  return m ? `thumbs/${m[1]}.webp` : null;
}
